bluesky.select(pl.col("j").str.json_path_match("$.commit.collection").alias("event")).group_by("event").agg(pl.len().alias("count")).sort("count", descending=True).collect()
bluesky.filter((pl.col("j").str.json_path_match("$.kind") == "commit") & (pl.col("j").str.json_path_match("$.commit.operation") == "create")).select(pl.col("j").str.json_path_match("$.commit.collection").alias("event"), pl.col("j").str.json_path_match("$.did").alias("did")).group_by("event").agg(pl.len().alias("count"), pl.col("did").drop_nulls().n_unique().alias("users")).sort("count", descending=True).collect()
bluesky.filter((pl.col("j").str.json_path_match("$.kind") == "commit") & (pl.col("j").str.json_path_match("$.commit.operation") == "create")).with_columns(pl.col("j").str.json_path_match("$.commit.collection").alias("event")).filter(pl.col("event").is_in(["app.bsky.feed.post", "app.bsky.feed.repost", "app.bsky.feed.like"])).select("event", pl.from_epoch(pl.col("j").str.json_path_match("$.time_us").cast(pl.Int64, strict=False), time_unit="us").dt.hour().alias("hour_of_day")).group_by("event", "hour_of_day").agg(pl.len().alias("count")).sort(["hour_of_day", "event"]).collect()
bluesky.filter((pl.col("j").str.json_path_match("$.kind") == "commit") & (pl.col("j").str.json_path_match("$.commit.operation") == "create") & (pl.col("j").str.json_path_match("$.commit.collection") == "app.bsky.feed.post")).select(pl.col("j").str.json_path_match("$.did").alias("user_id"), pl.from_epoch(pl.col("j").str.json_path_match("$.time_us").cast(pl.Int64, strict=False), time_unit="us").alias("ts")).group_by("user_id").agg(pl.col("ts").min().alias("first_post_date")).sort("first_post_date", nulls_last=True).head(3).collect()
bluesky.filter((pl.col("j").str.json_path_match("$.kind") == "commit") & (pl.col("j").str.json_path_match("$.commit.operation") == "create") & (pl.col("j").str.json_path_match("$.commit.collection") == "app.bsky.feed.post")).select(pl.col("j").str.json_path_match("$.did").alias("user_id"), pl.from_epoch(pl.col("j").str.json_path_match("$.time_us").cast(pl.Int64, strict=False), time_unit="us").alias("ts")).group_by("user_id").agg((pl.col("ts").max() - pl.col("ts").min()).dt.total_milliseconds().alias("activity_span")).sort("activity_span", descending=True, nulls_last=True).head(3).collect()
